'use client';

import { useState, type CSSProperties } from 'react';
import './dual-thumb-range.css';

export interface DualThumbRangeProps {
  value: [number, number];
  onChange: (value: [number, number]) => void;
  min: number;
  max: number;
  step?: number;
  /** Smallest allowed distance between the thumbs. */
  minGap?: number;
  /** Accessible names for the two thumbs. */
  labels: [string, string];
  format?: (value: number) => string;
  className?: string;
}

/**
 * Two native range inputs share one track, so each thumb works with drag,
 * touch and arrow keys on its own. The thumbs cannot cross, and each shows
 * its exact value above it.
 */
export function DualThumbRange({
  value,
  onChange,
  min,
  max,
  step = 1,
  minGap = 0,
  labels,
  format = String,
  className = '',
}: DualThumbRangeProps) {
  const [low, high] = value;
  const [active, setActive] = useState<0 | 1 | null>(null);
  const pct = (v: number) => ((v - min) / (max - min)) * 100;

  return (
    <div
      className={`mg-dual ${className}`}
      data-active={active ?? 'none'}
      style={
        {
          '--mg-low': `${pct(low)}%`,
          '--mg-high': `${pct(high)}%`,
        } as CSSProperties
      }
    >
      <div className='mg-dual__track' aria-hidden='true'>
        <span className='mg-dual__fill' />
      </div>
      <output
        className='mg-dual__bubble mg-dual__bubble--low'
        aria-hidden='true'
      >
        {format(low)}
      </output>
      <output
        className='mg-dual__bubble mg-dual__bubble--high'
        aria-hidden='true'
      >
        {format(high)}
      </output>
      <input
        type='range'
        className='mg-dual__input'
        aria-label={labels[0]}
        aria-valuetext={format(low)}
        min={min}
        max={max}
        step={step}
        value={low}
        onFocus={() => setActive(0)}
        onBlur={() => setActive(null)}
        onChange={(event) =>
          onChange([Math.min(Number(event.target.value), high - minGap), high])
        }
      />
      <input
        type='range'
        className='mg-dual__input'
        aria-label={labels[1]}
        aria-valuetext={format(high)}
        min={min}
        max={max}
        step={step}
        value={high}
        onFocus={() => setActive(1)}
        onBlur={() => setActive(null)}
        onChange={(event) =>
          onChange([low, Math.max(Number(event.target.value), low + minGap)])
        }
      />
    </div>
  );
}

.mg-dual {
  position: relative;
  height: 64px;
  color: var(--mg-ink, #0c1738);
}

.mg-dual__track {
  position: absolute;
  top: 42px;
  right: 11px;
  left: 11px;
  height: 6px;
  border-radius: 3px;
  background: #e1e8fb;
}

.mg-dual__fill {
  position: absolute;
  top: 0;
  bottom: 0;
  left: var(--mg-low);
  right: calc(100% - var(--mg-high));
  border-radius: 3px;
  background: var(--mg-accent, #164cff);
  transition:
    left 120ms ease-out,
    right 120ms ease-out;
}

.mg-dual__bubble {
  position: absolute;
  top: 0;
  padding: 2px 6px;
  border-radius: 6px;
  background: var(--mg-ink, #0c1738);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  transform: translateX(-50%);
  transition: left 120ms ease-out;
}

.mg-dual__bubble--low {
  left: calc(11px + (100% - 22px) * var(--mg-low) / 100%);
}

.mg-dual__bubble--high {
  left: calc(11px + (100% - 22px) * var(--mg-high) / 100%);
}

.mg-dual[data-active='0'] .mg-dual__bubble--low,
.mg-dual[data-active='1'] .mg-dual__bubble--high {
  background: var(--mg-accent, #164cff);
}

/* Both inputs span the track; only their thumbs take pointer input. */
.mg-dual__input {
  position: absolute;
  top: 32px;
  left: 0;
  width: 100%;
  height: 26px;
  margin: 0;
  background: none;
  pointer-events: none;
  appearance: none;
  -webkit-appearance: none;
}

.mg-dual__input::-webkit-slider-runnable-track {
  background: none;
}

.mg-dual__input::-moz-range-track {
  background: none;
}

.mg-dual__input::-webkit-slider-thumb {
  width: 22px;
  height: 22px;
  border: 3px solid var(--mg-accent, #164cff);
  border-radius: 50%;
  background: #fff;
  pointer-events: auto;
  cursor: grab;
  -webkit-appearance: none;
}

.mg-dual__input::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border: 3px solid var(--mg-accent, #164cff);
  border-radius: 50%;
  background: #fff;
  pointer-events: auto;
  cursor: grab;
}

.mg-dual__input:focus-visible::-webkit-slider-thumb {
  outline: 3px solid var(--mg-ink, #0c1738);
  outline-offset: 2px;
}

.mg-dual__input:focus-visible::-moz-range-thumb {
  outline: 3px solid var(--mg-ink, #0c1738);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-dual__fill,
  .mg-dual__bubble {
    transition: none;
  }
}
